:root {
  color-scheme: dark;
}

html,
body {
  margin: 0;
  min-height: 100%;
  background: #05070d;
  font-family: system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
}

.home {
  box-sizing: border-box;
  min-height: 100vh;
  padding: 24px 0 48px;
  color: #e5e7eb;
}

.home-loading {
  margin: 0;
  padding: 0 32px;
  color: #9ca3af;
  font-size: 15px;
}

.rows {
  display: grid;
  gap: 20px;
}

.row {
  min-width: 0;
}

.row-title {
  margin: 0 0 8px;
  padding: 0 32px;
  font-size: 17px;
  font-weight: 600;
}

/* The row scrolls sideways; focusing a tile brings it into view. */

.row-tiles {
  display: flex;
  gap: 14px;
  padding: 10px 32px 14px;
  overflow-x: auto;
  scrollbar-width: none;
}

.row-tiles::-webkit-scrollbar {
  display: none;
}

.tile,
.row-placeholder {
  box-sizing: border-box;
  flex: 0 0 auto;
  width: 176px;
  aspect-ratio: 16 / 9;
  border-radius: 8px;
}

.tile {
  position: relative;
  display: grid;
  place-items: center;
  padding: 0;
  overflow: hidden;
  border: 0;
  background: #1f2937;
  color: #f8fafc;
  font: inherit;
  cursor: pointer;
  transition: transform 140ms ease, box-shadow 140ms ease;
}

/* The focused tile grows and gets a ring, as on a TV. */

.tile:focus {
  outline: none;
  transform: scale(1.08);
  box-shadow: 0 0 0 3px #f8fafc, 0 10px 24px rgba(0, 0, 0, 0.6);
}

.tile-image {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.tile-fallback {
  padding: 0 12px;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.3;
  text-align: center;
}

.row-placeholder {
  display: grid;
  place-items: center;
  width: min(560px, calc(100vw - 64px));
  aspect-ratio: auto;
  height: calc(176px * 9 / 16);
  background: #111827;
  color: #6b7280;
  font-size: 14px;
}

.row-placeholder:focus {
  outline: 3px solid #f8fafc;
  outline-offset: 2px;
}

.details-backdrop {
  position: fixed;
  inset: 0;
  display: grid;
  place-items: center;
  padding: 16px;
  background: rgba(2, 6, 23, 0.82);
}

.details {
  box-sizing: border-box;
  width: min(520px, 100%);
  padding: 24px;
  border-radius: 14px;
  background: #0f172a;
  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.6);
}

.details-title {
  margin: 0;
  font-size: 24px;
}

.details-year {
  margin: 4px 0 0;
  color: #9ca3af;
  font-size: 14px;
}

.details-description {
  margin: 12px 0 0;
  font-size: 15px;
  line-height: 1.5;
}

.details-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 20px;
}

.play,
.watchlist {
  padding: 10px 18px;
  border: 2px solid #334155;
  border-radius: 8px;
  background: #1e293b;
  color: #f8fafc;
  font: inherit;
  font-size: 15px;
  cursor: pointer;
}

.play:focus,
.watchlist:focus {
  outline: none;
  border-color: #f8fafc;
  background: #334155;
}

.watchlist[aria-pressed="true"]::before {
  content: "\2713  ";
}

.details-status {
  min-height: 1.4em;
  margin: 14px 0 0;
  color: #93c5fd;
  font-size: 14px;
}

@media (max-width: 560px) {
  .row-title {
    padding: 0 16px;
  }

  .row-tiles {
    padding: 8px 16px 12px;
  }

  .tile,
  .row-placeholder {
    width: 136px;
  }

  .row-placeholder {
    width: calc(100vw - 32px);
    height: calc(136px * 9 / 16);
  }

  .home-loading {
    padding: 0 16px;
  }
}
